package main

import (
	"fmt"
	"sync"
)

type List struct {
	data []int
}

func (l *List) Append(val int) {
	l.data = append(l.data, val)
}

func main() {
	list := &List{data: []int{}}}

// Create a mutex to protect the list
var mutex sync.Mutex

// Append elements to the list
for i := 0; i < 100; i++ {
	mutex.Lock()
	list.Append(i)
	mutex.Unlock()
}}

// Check if the list is modified atomically
for i := 0; i < 100; i++ {
	if list.data[i] != i {
		fmt.Println("List is not modified atomically")
		return
	}
}}

// Output: List is not modified atomically
