class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.graph = []

    def add_edge(self, u, v, weight):
        self.graph.append([u, v, weight])

    def print_path(self, src, dst, parent):
        if src == dst:
            path = [src]
            print("Path found:", path)
            return

        if parent[dst] == -1:
            print("Path not found")
            return

        self.print_path(src, parent[dst], parent)

    def find_path(self, src, dst):
        for vertex in self.vertices:
            if vertex == src or vertex == dst:
                return vertex

        self.graph.append([src, dst, -1])
        return -1

    def dijkstra(self, src, dst):
        for vertex in self.vertices:
            self.dijkstra_helper(vertex)

    def dijkstra_helper(self, vertex):
        if vertex == -1:
            return
        elif vertex not in self.vertices:
            return
        elif self.dijkstra_helper(vertex) < 0:
            return

        for edge in self.graph:
            if edge[0] == edge[2] == edge[1] == vertex:
                if edge[1] == src and edge[1] != dst:
                    edge[2] = self.find_path(edge[0], edge[1]))


